<!-- --------- новый код chat: карточка материала цеха -->
<template><WorkOrderDialog :title="material?'Изменить материал':'Новый материал'" :busy="busy" @close="$emit('close')"><form @submit.prevent="save"><div v-if="error" class="alert alert-danger">{{ error }}</div><fieldset :disabled="busy" class="border-0 p-0"><label class="form-label">Наименование</label><input v-model="form.name" required maxlength="200" class="form-control form-control-sm mb-3"><label class="form-label">Цех</label><select v-model="form.workshop_id" required class="form-select form-select-sm mb-3"><option :value="0" disabled>Выберите цех</option><option v-for="s in refs.workshops" :key="s.ID" :value="s.ID">{{ s.name }}</option></select><label class="form-label">Единица измерения</label><select v-model="form.unit_id" required class="form-select form-select-sm"><option :value="0" disabled>Выберите единицу</option><option v-for="u in refs.units" :key="u.ID" :value="u.ID">{{ u.name }}</option></select><p class="text-secondary mt-2">После поступлений или использования цех и единицу изменить нельзя.</p><button class="btn btn-primary btn-sm">Сохранить</button></fieldset></form></WorkOrderDialog></template>
<script setup>
import {ref,reactive} from 'vue';import api from '../../../api';import WorkOrderDialog from './WorkOrderDialog.vue';import {workError} from './workOrderHelpers';
const props=defineProps({agreementId:[String,Number],material:Object,refs:Object});const emit=defineEmits(['close','saved']);const busy=ref(false),error=ref('');const form=reactive({name:props.material?.name||'',workshop_id:props.material?.workshop_id||0,unit_id:props.material?.unit_id||0});
const save=async()=>{if(busy.value)return;busy.value=true;try{const url=`/agreements/${props.agreementId}/warehouse`;if(props.material)await api.patch(`${url}/${props.material.ID}`,form);else await api.post(`${url}/create`,form);emit('saved');}catch(e){error.value=workError(e);}finally{busy.value=false;}};
</script>
<!-- --------- конец нового кода chat -->
